Q = []


def add(q, correct, wrong, explain, without, with_, benefit, code=False):
    assert len(wrong) == 3, q
    Q.append(dict(q=q, correct=correct, wrong=wrong, explain=explain,
                  usage=dict(code=code, without=without, with_=with_, benefit=benefit)))


def mat(*rows):
    """LaTeX bmatrix без разделителей формулы: mat([2, 1], [1, 2])."""
    return r"\begin{bmatrix}" + r"\\".join("&".join(str(x) for x in r) for r in rows) + r"\end{bmatrix}"


def col(*xs):
    return mat(*[[x] for x in xs])


def T(s, **kw):
    """Подстановка @имя@ → значение (format мешал бы фигурным скобкам LaTeX)."""
    for k, v in kw.items():
        s = s.replace("@" + k + "@", v)
    return s


